from itertools import product
G=['0110110','1111110','0110100','0011100']
# positions 4x7, occupied
occ={(r,c) for r,row in enumerate(G) for c,v in enumerate(row) if v=='1'}
shapes={1:{(0,0),(0,1),(1,0),(1,1)},2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)}}
placements=[]
for color,shape in shapes.items():
 for r in range(3):
  for c in range(6):
   cells={(r+dr,c+dc) for dr,dc in shape}
   if cells<=occ: placements.append((color,cells,(r,c)))
solutions=[]
def rec(rem, chosen):
 if not rem:
  solutions.append(chosen);return
 x=min(rem)
 for p in placements:
  if x in p[1] and p[1]<=rem:
   rec(rem-p[1],chosen+[p])
rec(occ,[])
print('occupancy',len(occ),'placements',len(placements),'solutions',len(solutions))
for sol in solutions[:10]:
 print([(x[0],x[2], sorted(x[1])) for x in sol])
